import json,pathlib,re
r=pathlib.Path(__file__).parent
rows=[]
def add(k,exposure,endpoint,result,limitation,decision,role='primary',access='Primary abstract and metadata; full methods not independently recovered',finding=None):
 p=r/'sources'/f'{k}.json';s=json.loads(p.read_text());h=s['metadata'];a=h.get('authorList',{}).get('author',[]);names=[x.get('fullName','') for x in a];first=(a[0].get('lastName') if a else None) or h.get('authorString','').split(',')[0];label=f"{first} et al. ({h.get('pubYear')})"
 rows.append(dict(citation_key=k,doi=s.get('doi'),title=re.sub('<[^>]+>','',h.get('title','')),year=h.get('pubYear'),authors=names,label=label,publication_class=role,exposure=exposure,endpoint=endpoint,result=result,limitations=limitation,decision=decision,access=access,finding_id=finding,source_url='https://doi.org/'+s.get('doi',''),verified_on='2026-10-26'))
add('you_regional_release_2014','42 older abdominally obese women; 20-week hypocaloric programme, with or without aerobic exercise; pooled pre/post analysis. Ex vivo release measured in 27 women.','Abdominal/gluteal tissue leptin and adiponectin gene expression and ex vivo release; plasma separately.','Weight loss 10.1 ± 0.7 kg. Leptin release decreased in both depots; adiponectin release increased only abdominally. Tissue and circulating changes were not significantly correlated.','Release subgroup n=27, expression n=42. No untreated comparator for pooled analysis; exercise could not be isolated. Whole-tissue ex vivo release is not in vivo flux. Population, depot, weight loss and energy balance constrain interpretation.','Supports bounded dietary-programme SOP, not universal hormone optimisation.','primary','Full primary Methods/Results/Discussion and figures recovered through Scite; all 21,177 body characters reviewed.','PM8-F16')
add('arvidsson_hypocaloric_secretion_2004','40 women with obesity randomised to 10-week hypocaloric low-fat/high-carbohydrate or moderate-fat/moderate-carbohydrate diets; deficit 600 kcal/day.','Subcutaneous adipose ex vivo protein secretion and transcripts, with circulating concentrations separately.','Approximately 7.5% weight loss and 40% lower leptin secretion; adiponectin secretion unchanged. Diet arms had similar responses.','No weight-stable comparator; cannot separate energy deficit from weight loss. Adiponectin null qualifies You abdominal response; no macronutrient superiority. Tested deficit is a study exposure, not an effective-dose prescription.','Independent qualified support for dietary programme; retain null adiponectin result.','primary','Primary abstract and accessible journal/PDF excerpts; complete bias appraisal remains limited.','PM8-F16')
add('siklova_diet_phase_secretion_2012','48 women with obesity: 1-month very-low-calorie diet then 5 months stabilisation/maintenance; release subgroup 26, transcript subgroup 22.','Subcutaneous adipose explant secretion, transcripts and plasma during different programme phases.','Adipocyte-produced leptin measures fell during very-low-calorie feeding and rose during stabilisation; stromavascular adipokines followed different patterns.','Uncontrolled multiphase programme; cellular source and energy-balance phase matter. Does not justify sustained maximisation of leptin suppression or a general very-low-calorie diet recommendation.','Phase qualification of admitted dietary programme.','primary',finding='PM8-F16')
add('klein_leptin_fasting_2000','9 lean and 9 upper-body obese women studied after 14 and 22 hours fasting.','Abdominal adipose arteriovenous net leptin release and plasma.','Release declined in lean women but changed little in women with upper-body obesity.','Small acute physiology experiment; fasting duration, time of day and energy balance not independently isolated. Does not validate a fasting protocol or universal lower-leptin target.','Target engagement lead; no fasting SOP admission.','primary',finding='PM8-F16')
add('hojbjerre_exercise_adiponectin_2007','8 overweight and 8 lean men; rest comparison day versus 1 hour exercise at 55% VO2max with pre/post subcutaneous biopsy.','Local interstitial adiponectin by large-pore microdialysis; adipose transcripts and plasma separately.','Interstitial adiponectin increased despite unchanged plasma adiponectin and decreased adiponectin mRNA. Leptin mRNA decreased.','Interstitial concentration is not secretion rate; blood flow, recovery and compartment distribution matter. Acute small male sample does not define chronic response, receptor sensitivity or clinical benefit.','Supports bounded local exercise engagement, not a universal adiponectin-raising protocol.','primary',finding='PM8-F17')
add('moghadasi_endurance_adiponectin_2012','16 sedentary overweight/obese men randomised 8 training/8 control; 12 weeks, 4 days/week, 45 minutes at 75–80% VO2max.','Abdominal/gluteal adiponectin mRNA, plasma adiponectin and body composition.','Adiponectin mRNA and plasma increased; adiposity fell concurrently.','Transcription is not secretion or receptor responsiveness. Small sample; weight-independent mediation and optimal exercise dose not established.','Qualified training support; no generic secretion claim.','primary',finding='PM8-F17')
add('polak_aerobic_adipokines_2006','25 sedentary women with obesity; 12-week aerobic programme, 5 days/week at 50% VO2max; biopsy subgroup 8.','Subcutaneous adipose adipokine transcripts and circulating hormones.','No significant changes in tested tissue transcripts; plasma leptin fell, plasma adiponectin unchanged, despite weight/fat loss.','Small biopsy subgroup; uncontrolled pre/post design. Important contextual null, not direct refutation of a different acute interstitial measurement.','Retain contradictory/contextual evidence; limits exercise generalisation.','primary',finding='PM8-F17')
add('tishinsky_epa_adiponectin_2011','Isolated cultured human adipocytes exposed for 48 hours to 100 µM free EPA or DHA, with PPARγ perturbation and rosiglitazone comparisons.','Secreted adiponectin, intracellular protein and PPARγ-dependent response.','Adiponectin secretion rose 88% with EPA and 47% with DHA; antagonist responses differed.','Cultured free-fatty-acid exposure is not dietary delivery. Rosiglitazone is pharmacological; no ordinary-fish, food-dose or clinical equivalence.','Mechanistic Finding; nutrient admission deferred pending essential exposure/engagement bridge.','primary',finding='PM8-F18')
add('wu_fish_oil_adiponectin_2013','Systematic review/meta-analysis: 14 fish-oil trial arms, 682 intervention/641 control; two fish-feeding arms separately.','Circulating adiponectin, not adipose secretion.','Fish-oil pooled +0.37 µg/mL (95% CI 0.07–0.67), substantial heterogeneity; publication-bias adjustment +0.18 (−0.15 to 0.52). Fish-feeding estimate −0.01 (−0.65 to 0.64).','Secondary synthesis; do not double-count included trials. Blood concentration does not identify secretion mechanism; heterogeneous formulations and publication bias limit coherence.','Supports physiological dietary response but does not close local secretory mediation or ordinary-fish equivalence.','secondary','Full accessible review text and abstract; synthesis not an independent primary experiment.','PM8-F18')
add('stomby_diet_glucocorticoid_2015','49 postmenopausal women with overweight/obesity randomised to Paleolithic-type or Nordic-recommendation diets for 24 months.','Subcutaneous adipose 11β-HSD1 mRNA, hepatic cortisone conversion and systemic metabolites.','Adipose 11β-HSD1 mRNA decreased at 6 and 24 months while weight fell; hepatic conversion increased transiently at 6 months.','Transcript is not local enzyme activity or cortisol-regeneration flux. Both diets produced weight loss; no independent effect of individual foods or weight-independent mechanism. Published 2015, online 2014.','Relevant local transcript evidence; retain contrast with Tomlinson and systemic Stimson null without claiming all dietary engagement absent.','primary',finding='PM8-F13')
add('evans_meal_leptin_2001','6 volunteers: oral 40 g fat/9.6 g carbohydrate versus intravenous fat; separate 8 volunteers: mixed meal 37 g fat/100 g carbohydrate.','Paired arterialised/adipose venous leptin concentration differences over 6 hours.','Leptin venous–arterial difference fell after fat loads and rose after the mixed meal, peaking at 240 minutes.','Different small cohorts, non-isolated carbohydrate, oral versus intravenous exposure. Concentration difference is not equivalent to fully quantified secretion flux. No optimal meal or carbohydrate requirement established.','Meal-related local engagement established narrowly; defer an actionable food/composition recommendation.','primary',finding='PM8-F16')
add('weigle_protein_leptin_2005','19 adults: sequential 15% protein, isocaloric 30% protein, then ad-libitum 30% protein diet.','24-hour circulating leptin and satiety, energy intake and weight.','Satiety increased on isocaloric higher protein without changed leptin AUC; ad-libitum phase reduced intake and weight with lower leptin.','Sequential design; central leptin sensitivity inferred, not measured. No direct adipose secretion/receptor assay or protein-specific PM8 admission.','No protein input admitted; preserve distinction between satiety, circulating leptin and receptor sensitivity.')
add('vujovic_late_eating_2022','Randomised isocaloric early/late meal crossover with controlled sleep, light and activity.','24-hour circulating leptin/ghrelin, expenditure and exploratory adipose transcription.','Later eating lowered circulating leptin and increased ghrelin/leptin ratio; exploratory tissue pathways differed.','Does not measure adipose leptin secretion or receptor responsiveness. Acute timing/energy-expenditure interactions; direction of leptin change is not an endocrine-benefit criterion.','Physiological timing evidence retained; no PM8-specific optimisation protocol admitted.')
add('ravussin_early_feeding_2019','11 adults; 4-day crossover of eating 08:00–14:00 versus 08:00–20:00 with matched food.','Appetite, ghrelin, expenditure and fat oxidation.','Early feeding altered appetite/ghrelin and substrate oxidation.','Ghrelin/appetite are not adipose adipokine secretion or local glucocorticoid responsiveness. Small, short study.','Timing candidate deferred for PM8; no transfer to another PM without its own admission.')
add('wehrens_meal_timing_2017','10 men; meals delayed 5 hours.','Circadian glucose and subcutaneous adipose PER2 expression.','Adipose clock timing shifted; systemic and peripheral clocks distinguished.','Adipose tissue measurement alone does not establish adipokine output, receptor responsiveness or local cortisol regeneration.','Circadian source lead; not PM8 intervention engagement.')
add('wholegrain_adiponectin_2019','12-week isoenergetic whole-grain versus refined-grain comparison.','Plasma adiponectin and faecal SCFA.','Adiponectin increased in both groups; associations with SCFA did not establish mediation.','No specific whole-grain superiority, direct adipose secretion or microbial causal mediation. Published 2020, online 2019.','Fibre/whole-grain candidate not admitted for PM8.')
add('javadi_prebiotic_adipokines_2017','89 adults with NAFLD; 12-week probiotic, oligofructose 16 g/day or maltodextrin; shared diet/activity advice.','Serum leptin/adiponectin and metabolic measures.','Serum leptin changes did not establish a specific adipose secretory pathway; no between-group adiponectin benefit.','Systemic concentrations, shared co-interventions and disease context; no traced microbial mediation or isolated inulin equivalence.','Prebiotic candidate deferred; no food/input admission.')
add('medina_adiponectin_2023','42 NAFLD participants randomised Mediterranean diet (19) or low-fat diet (23), 12 weeks.','Circulating adiponectin/leptin.','Adiponectin increased within Mediterranean arm; low-fat arm showed greater leptin reduction.','Within-arm significance is not between-arm superiority. No tissue secretion or component attribution.','Whole-pattern physiological evidence retained; no PM8-specific Mediterranean/component SOP admitted.')
add('fatouros_resistance_adipokines_2005','50 older men randomised control or three resistance-training intensities, 6 months, then detraining.','Circulating leptin/adiponectin and body composition.','Training-dependent circulating changes accompanied body-composition changes.','No adipose synthesis/secretion or receptor responsiveness measured; weight mediation not isolated.','Resistance training candidate deferred for a PM8-specific protocol.')
add('mansouri_resistance_adiponectin_2011','34 young trained/untrained men assigned acute resistance exercise or control; 120 minutes at 70–80% 1RM.','Circulating adiponectin/RBP4 over four hours.','No significant acute adiponectin or RBP4 response.','Acute serum null does not disprove chronic or local endocrine effects.','Retain null; no PM8 resistance protocol admitted.')
add('spiegel_sleep_leptin_2004','12 healthy young men; randomised 2-day 4-hour versus 10-hour sleep opportunity under controlled calories/activity.','Circulating leptin/ghrelin, hunger/appetite.','Restricted sleep lowered leptin and raised ghrelin and hunger.','No adipose secretion, receptor or 11β-HSD1 assay; expenditure unmeasured. Acute restriction is not proof of benefit from extension/regularity.','Sleep candidate retained, no adipose-specific lifestyle admission.')
add('sleep_adipokines_meta_2015','Systematic review/meta-analysis of randomised sleep-duration experiments.','Energy balance, adiposity and circulating hormone outcomes.','Pooled leptin analysis did not establish a significant effect; heterogeneity substantial.','Secondary synthesis, variable energy-balance conditions and small hormone subset; no local adipose target measurement.','Qualifies single-study sleep signal; no universal direction claimed.','secondary')
add('broussard_sleep_adipocyte_2012','7 adults; randomised crossover sleep restriction versus adequate sleep, with adipose biopsies.','Adipocyte insulin-stimulated AKT signalling.','Insulin signalling impaired after restricted sleep.','Direct tissue endpoint belongs primarily to insulin responsiveness/glucose-disposal ownership; does not measure adipokine or glucocorticoid output.','Ownership distinction preserved; no PM8 admission or automatic transfer.')
add('niacin_adipokines_2006','30 men with metabolic syndrome; 20 extended-release niacin 1500 mg/day, 10 placebo, 6 weeks.','Circulating adiponectin/leptin, HOMA and endothelial measures.','Adiponectin and leptin rose, while HOMA insulin resistance worsened; no endothelial improvement.','Pharmacological dose/formulation, not ordinary-food niacin supply. Hormone increases do not establish benefit; no local secretion assay.','Not admitted as dietary niacin; Type A dependency/supply assessment remains distinct.')
(r/'evidence-matrix.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
print(len(rows),'reviewed evidence rows')
